import type { IconifyJSON } from '@iconify/types';
import { addCollection } from '@iconify/vue';
import { type Ref, ref } from 'vue';

// Offline devicon registration shared by every surface that renders
// `devicon:*` glyphs: no runtime calls to the Iconify API — the CSP
// `connect-src 'self'` policy would block the fallback fetches the
// Iconify runtime attempts for unregistered names. The devicon subset
// generated by `npm run icons:build` (scripts/build-icon-subsets.mjs)
// ships through one lazy dynamic import (idempotent — a single shared
// registry, unlike the per-feature public iconRegistration modules that
// also bundle their extra packs). The `iconsReady` ref lets consumers
// render their `<Icon>` elements only after registration — a
// non-reactive storage would leave them empty until an unrelated
// re-render (and the first paint would trigger remote fetch attempts).

let registered = false;
const iconsReady = ref(false);

export function useDeviconIconsReady(): Ref<boolean> {
    return iconsReady;
}

export function ensureDeviconIcons(): void {
    if (registered || typeof window === 'undefined') {
        return;
    }

    registered = true;

    void import('@/iconSubsets/devicon.json')
        .then((devicon) => {
            addCollection((devicon as { default: IconifyJSON }).default);
            iconsReady.value = true;
        })
        .catch(() => {
            // Iconify falls back to its runtime fetch on an unregistered
            // name; the icons stay empty until a later registration.
            registered = false;
        });
}
